SELECT
pt.id,pt.pid,pt.phase_id,pt.phase_name,pt.name,pt.type,pt.plan_start_time,pt.plan_end_time,pt.priority,pt.status,pt.is_fixed,
pt.charge_name,pt.quote_sys_task_id,pt.product_id,pt.charge_id,pt.process_id,pt.role_name,pt.distribution_type
FROM project_task pt
left join product_info pdi on pt.product_id = pdi.id
left join project_info pji on pdi.id = pji.product_id
left join task_charge_distribution tcd on pt.id = tcd.task_id and tcd.source = 3
where  (pdi.approval_status is null or pdi.approval_status != 5) and (pji.project_status is null or
    pji.project_status != 4)


            AND pt.product_id = #{params.groupFlag}



                AND pt.process_id IN

                    #{processId}






            AND pt.plan_end_time >= #{params.startTime}


            AND pt.plan_end_time <= #{params.endTime}



                AND pt.process_id IN

                    #{processId}





        AND pt.status NOT IN

            #{state}



        AND pt.name LIKE concat('%',#{params.searchKeyword},'%')


        AND (not EXISTS (select a.pre_task_id from pre_task a where a.task_id = pt.id) or not EXISTS (select
        b.id from pre_task a left join project_task b on a.pre_task_id = b.id where b.status != 4 and a.task_id
        = pt.id ))


        AND EXISTS (select b.id from pre_task a left join project_task b on a.pre_task_id = b.id where (b.status
        = 1 or b.status = 3) and a.task_id = pt.id)



            AND pt.name LIKE concat('%',#{params.taskSearchDTO.searchKeyword},'%')


            AND pt.priority in

                #{priority}



            AND pt.charge_id in

                #{chargeId}



            AND pt.status in

                #{status}



            AND pt.create_time >= #{params.taskSearchDTO.startTime}


            AND pt.end_time <= #{params.taskSearchDTO.endTime}



        ${params.param}

    ORDER BY


            pt.${item.field} ${item.sort}


    pt.update_time desc

SELECT id,pid,phase_id,phase_name,name,type,plan_start_time,plan_end_time,priority,status,
charge_name,quote_sys_task_id,product_id,charge_id,process_id FROM project_task
WHERE  status!=#{state}
AND plan_end_time >= #{startTime}  AND plan_end_time <= #{endTime}
UNION ALL
SELECT id,pid,phase_id,phase_name,name,type,plan_start_time,plan_end_time,priority,status,
charge_name,quote_sys_task_id,product_id,charge_id,process_id FROM project_task
WHERE   status!=#{state} AND plan_end_time < #{startTime}

select t.* from (select pi.id as productId, pi.name as productName, pi.approval_status, pt.name as taskName, to_char(pt.plan_start_time, 'yyyy-MM-dd') as plan_start_time, to_char(pt.plan_end_time, 'yyyy-MM-dd') as plan_end_time, to_char(pt.reality_start_time, 'yyyy-MM-dd') as reality_start_time, to_char(pt.reality_end_time, 'yyyy-MM-dd') as reality_end_time, pt.id as taskId, pt.status, regexp_split_to_table(pt.charge_id,',') as charge_id, regexp_split_to_table(pt.charge_name,',') as charge_name, pt.phase_name, pi2.project_status, case when pt.plan_end_time is null then 0 when to_char(pt.plan_end_time, 'YYYYMMDD') >= to_char(now(), 'YYYYMMDD') then 0 when to_char(now(), 'YYYYMMDD') > to_char(pt.plan_end_time, 'YYYYMMDD') and pt.status != 4 and pt.status != 5 then 1 else 0 end isDelay from product_info pi inner join project_task pt on pi.id = pt.product_id left join project_info pi2 on pi.id = pi2.product_id where pi.is_finished_product_dev = 1 ) t
and
string_to_array(t.charge_id,',') && string_to_array(#{item}, ',')
and t.productId in
#{item}
and t.status in
#{item}
and t.approval_status in
#{item}
and t.project_status in
#{item}
${dto.param}
order by t.charge_id desc, t.plan_end_time asc, t.taskId desc

