SELECT id AS taskId, project_id, pid, product_id, name, type, charge_id, charge_name, plan_start_time, plan_end_time, reality_start_time, reality_end_time, priority, phase_id, phase_name, description, is_milepost, create_user_name, create_time, update_time, update_user_name FROM project_task WHERE product_id=#{dto.productId}
AND property=1
AND property=2
AND string_to_array(charge_id,',') && string_to_array(dto.taskChargeId,',')
AND name LIKE concat('%',#{dto.searchKeyword},'%'
AND plan_start_time >= #{dto.planStartTime}
AND plan_end_time <= #{dto.planEndTime}
ORDER BY
${item.field} ${item.sort}
